<template><section class="card profile"><h1>个人资料</h1><p v-if="loading">加载中…</p><template v-else-if="auth.user"><dl><dt>用户名</dt><dd>{{ auth.user.username }}</dd><dt>邮箱</dt><dd>{{ auth.user.email }}</dd><dt>状态</dt><dd>{{ auth.user.status }}</dd><dt>角色</dt><dd>{{ auth.user.roles.join('、') }}</dd></dl><button @click="auth.logout">退出登录</button></template><p v-else class="error">无法加载用户信息</p></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; const auth = useAuthStore(); const router = useRouter(); const loading = ref(true); onMounted(async () => { try { await auth.fetchProfile() } catch { auth.clear(); router.push('/login') } finally { loading.value = false } })</script>
